/* Stand-in for the part of xscreensaver's utils/visual.h that hacks use. Not
 * derived from xscreensaver code. */
#ifndef XSHIM_VISUAL_H
#define XSHIM_VISUAL_H

#include "x11shim/xshim.h"

#ifdef __cplusplus
extern "C" {
#endif

/* The display is always 16-bit RGB565, whatever visual is asked about. */
int visual_depth(Screen *, Visual *);

#ifdef __cplusplus
}
#endif

#endif

/* Stand-in for xscreensaver's utils/xshm.h. There is no X server to share
 * memory with: an "shm" image is an ordinary 16-bit XImage in the hack's own
 * memory, and putting it is XPutImage. Not derived from xscreensaver code. */
#ifndef XSHIM_XSHM_H
#define XSHIM_XSHM_H

#include "visual.h"
#include "x11shim/xshim.h"

#ifdef __cplusplus
extern "C" {
#endif

/* Holds nothing: the image owns its memory. */
typedef struct {
  int unused;
} XShmSegmentInfo;

/* A zeroed w by h image of the given depth, or NULL for a depth XCreateImage
 * does not make or no memory. Free it with destroy_xshm_image. */
XImage *create_xshm_image(Display *, Visual *, unsigned int depth, int format,
                          XShmSegmentInfo *, unsigned int w, unsigned int h);

/* XPutImage of the region, clipped to the drawable. */
void put_xshm_image(Display *, Drawable, GC, XImage *, int src_x, int src_y,
                    int dest_x, int dest_y, unsigned int w, unsigned int h,
                    XShmSegmentInfo *);

void destroy_xshm_image(Display *, XImage *, XShmSegmentInfo *);

#ifdef __cplusplus
}
#endif

#endif

/* The shared-memory image calls and visual_depth, over plain XImages. Written
 * for this project; not derived from xscreensaver's utils. */
#include <stdlib.h>

#include "visual.h"
#include "xshm.h"

int visual_depth(Screen *screen, Visual *visual) {
  (void)screen;
  (void)visual;
  return 16;
}

XImage *create_xshm_image(Display *dpy, Visual *visual, unsigned int depth,
                          int format, XShmSegmentInfo *shm, unsigned int w,
                          unsigned int h) {
  (void)shm;
  XImage *im = XCreateImage(dpy, visual, depth, format, 0, NULL, w, h, 16, 0);
  if (!im) return NULL;
  im->data = (char *)calloc(h, (size_t)im->bytes_per_line);
  if (!im->data) {
    XDestroyImage(im);
    return NULL;
  }
  return im;
}

void put_xshm_image(Display *dpy, Drawable d, GC gc, XImage *im, int src_x,
                    int src_y, int dest_x, int dest_y, unsigned int w,
                    unsigned int h, XShmSegmentInfo *shm) {
  (void)shm;
  XPutImage(dpy, d, gc, im, src_x, src_y, dest_x, dest_y, w, h);
}

void destroy_xshm_image(Display *dpy, XImage *im, XShmSegmentInfo *shm) {
  (void)dpy;
  (void)shm;
  XDestroyImage(im);
}

